// Title: Export a workbook with an embedded PNG to HTML and count <img> tags using Aspose.Cells in C#
// Common Searches: how to export an Aspose.Cells workbook to HTML and get the number of images in C# | C# code to count <img> elements in HTML generated by Aspose.Cells | using Aspose.Cells to insert a picture into a worksheet and then parse the HTML output for image tags | regex pattern for counting img tags in Aspose.Cells HTML export C# | retrieve image count from HTML file created by Aspose.Cells workbook save
// Tags: Aspose.Cells export workbook to HTML | Aspose.Cells insert picture into worksheet | C# count img tags in HTML | regex match img elements C# | parse Aspose.Cells HTML output for images

using System;
using System.IO;
using System.Text.RegularExpressions;
using Aspose.Cells;

// The example creates a new Workbook, adds a 1x1 red PNG image to cell A1, saves the workbook as an HTML file with Aspose.Cells, reads the generated HTML, uses a case‑insensitive regular expression to count <img> tags, and writes the image count to the console while handling potential errors.
class Program
{
    static void Main()
    {
        try
        {
            // Create a new workbook and get the first worksheet
            Workbook workbook = new Workbook();
            Worksheet worksheet = workbook.Worksheets[0];

            // Base64-encoded 1x1 red PNG image
            const string redPngBase64 = "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+XK0cAAAAASUVORK5CYII=";
            byte[] imageBytes = Convert.FromBase64String(redPngBase64);

            // Insert the image into cell A1 (row 0, column 0)
            using (MemoryStream imageStream = new MemoryStream(imageBytes))
            {
                worksheet.Pictures.Add(0, 0, imageStream);
            }

            // Define HTML output path
            string htmlFilePath = "output.html";

            // Save workbook as HTML
            workbook.Save(htmlFilePath, SaveFormat.Html);

            // Ensure the HTML file was created
            if (!File.Exists(htmlFilePath))
                throw new FileNotFoundException("HTML output file was not created.", htmlFilePath);

            // Read the generated HTML
            string htmlContent = File.ReadAllText(htmlFilePath);

            // Count <img> tags using a simple regex (case‑insensitive)
            int imageTagCount = Regex.Matches(htmlContent, @"<img\b", RegexOptions.IgnoreCase).Count;

            // Output the result
            Console.WriteLine($"Number of <img> tags: {imageTagCount}");
        }
        catch (Exception ex)
        {
            // Log any unexpected errors
            Console.Error.WriteLine($"Error: {ex.Message}");
        }
    }
}
